// Normalize Email — Tooba support Slack MVP
// Extract real customer email, subject, and clean text from Outlook Raw payload.

const item = $input.first().json;

function getEmailAddress(obj) {
  const ea = obj?.emailAddress || obj || {};
  return {
    name: (ea.name || ea.displayName || '').trim(),
    address: (ea.address || ea.email || ea.emailAddress || '').toLowerCase().trim(),
  };
}

function htmlToText(input) {
  if (!input) return '';

  return String(input)
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const messageId = item.id || item.messageId || null;
const internetMessageId = item.internetMessageId || null;
const subject = (item.subject || '(No Subject)').trim();
const receivedDateTime = item.receivedDateTime || item.createdDateTime || '';

const rawBody = item.body?.content || item.bodyPreview || '';
let cleanBody = htmlToText(rawBody);

// Tooba feedback emails often contain the real sender in body:
// "Отправлено от oxotnik37@rambler.ru"
const embeddedSenderMatch = cleanBody.match(/Отправлено от\s+([^\s<>]+@[^\s<>]+)/i);
const embeddedSenderEmail = embeddedSenderMatch?.[1]?.toLowerCase()?.trim() || '';

// Remove technical "Отправлено от ..." line from customer text.
cleanBody = cleanBody
  .replace(/\n?\s*Отправлено от\s+[^\s<>]+@[^\s<>]+/i, '')
  .trim();

const from = getEmailAddress(item.from);
const sender = getEmailAddress(item.sender);

const replyTo = Array.isArray(item.replyTo) && item.replyTo.length
  ? getEmailAddress(item.replyTo[0])
  : { name: '', address: '' };

const ccCustomer = Array.isArray(item.ccRecipients)
  ? item.ccRecipients
      .map(getEmailAddress)
      .find(e =>
        e.address &&
        !e.address.includes('support@tooba.com') &&
        !e.address.includes('@tooba.com') &&
        !e.address.includes('@mx.tooba.com')
      )
  : null;

// Priority:
// 1. replyTo
// 2. ccRecipients external email
// 3. embedded "Отправлено от ..."
// 4. from
// 5. sender
let customer = replyTo.address
  ? replyTo
  : ccCustomer?.address
    ? ccCustomer
    : embeddedSenderEmail
      ? { name: embeddedSenderEmail, address: embeddedSenderEmail }
      : from.address
        ? from
        : sender;

let senderEmail = customer.address || 'UNKNOWN';
let senderName = customer.name || senderEmail;

if (!senderName || senderName.toLowerCase() === senderEmail.toLowerCase()) {
  senderName = senderEmail;
}

let skip = false;
let skipReason = '';

if (!messageId) {
  skip = true;
  skipReason = 'messageId missing';
}

if (!skip && item.isDraft === true) {
  skip = true;
  skipReason = 'item is draft';
}

if (!skip && senderEmail.includes('support@tooba.com')) {
  skip = true;
  skipReason = 'own support email';
}

if (!skip && cleanBody.length < 3) {
  skip = true;
  skipReason = 'empty cleanBody';
}

// For this MVP, do not process unrelated subjects.
if (!skip && !subject.toLowerCase().includes('tooba feedback')) {
  skip = true;
  skipReason = 'subject does not include Tooba Feedback';
}

return [{
  json: {
    messageId,
    internetMessageId,
    senderName,
    senderEmail,
    subject,
    receivedDateTime,
    cleanBody,
    rawBody,
    webLink: item.webLink || null,
    conversationId: item.conversationId || null,
    skip,
    skipReason
  }
}];

// Build AI Prompt — Tooba Support AI Slack MVP
// Minimal prompt. No hardcoded FAQ — add your knowledge base here when ready.

const email = $input.first().json;

const systemPrompt = `Ты — ассистент службы поддержки Tooba.
Отвечай вежливо, кратко и по делу на вопрос клиента.
Если точного ответа нет — честно скажи об этом.
НЕ ПИШИ вводные фразы: "Вот черновик:", "Добрый день, предлагаю:" и подобные.
В конце ВСЕГДА добавляй подпись:

С уважением,
Команда поддержки Tooba`;

const userPrompt = `Тема письма: ${email.subject}

Письмо клиента:
${email.cleanBody}`;

return [{ json: { systemPrompt, userPrompt, email } }];

// Extract AI Reply — Tooba Support AI Slack MVP

const response = $input.first().json;
const email = $('🤖 Build AI Prompt').first().json.email;
const slackTs = $('💬 Post Email to Slack').first().json.ts;

let aiReply = '';
let aiError = false;
let errorMessage = '';

if (response?.error) {
  const err = response.error;
  errorMessage = err.message || JSON.stringify(err);
  const isRateLimit =
    String(err.code || '').includes('rate_limit') ||
    String(err.type || '').includes('rate_limit') ||
    errorMessage.toLowerCase().includes('429') ||
    errorMessage.toLowerCase().includes('rate limit') ||
    errorMessage.toLowerCase().includes('too many requests');
  aiReply = isRateLimit
    ? 'Нет подходящего ответа — требуется проверка менеджера. Причина: OpenAI rate limit.'
    : 'Нет подходящего ответа — требуется проверка менеджера.';
  aiError = true;
}

if (!aiReply) {
  aiReply = (
    response?.choices?.[0]?.message?.content ||
    response?.output_text ||
    response?.message?.content ||
    response?.text ||
    ''
  ).trim();
}

if (!aiReply) {
  aiReply = 'Нет подходящего ответа — требуется проверка менеджера.';
  aiError = true;
  if (!errorMessage) errorMessage = 'Empty or unexpected response from OpenAI';
}

return [{
  json: {
    aiReply,
    aiError,
    errorMessage,
    messageId: email.messageId,
    senderName: email.senderName,
    senderEmail: email.senderEmail,
    subject: email.subject,
    cleanBody: email.cleanBody,
    slackTs
  }
}];

